function mark(){
 return '<span>V</span><span class="o"><i class="ray r1"></i><i class="ray r2"></i><i class="ray r3"></i></span><span>CE</span>';
}
function currentLang(){return localStorage.getItem("voce-lang")||"en"}
function setLang(l){
 localStorage.setItem("voce-lang",l);
 renderTopic(l);
}
function renderTopic(l){
 const d=TOPICS[window.VOCE_TOPIC][l]||TOPICS[window.VOCE_TOPIC].en;
 const c=COMMON[l]||COMMON.en;
 document.documentElement.lang=l;
 document.title=d.title+" — VOCE";
 document.querySelectorAll("[data-lang]").forEach(b=>{b.classList.toggle("active",b.dataset.lang===l);b.setAttribute("aria-pressed",b.dataset.lang===l?"true":"false")});
 document.querySelectorAll(".voce-mark").forEach(el=>el.innerHTML=mark());
 document.querySelector("[data-nav-themes]").textContent=c.themes;
 document.querySelector("[data-nav-publications]").textContent=c.publications;
 document.querySelector("[data-nav-committee]").textContent=c.committee;
 document.querySelector("[data-nav-about]").textContent=c.about;
 document.querySelector("#topic-kicker").textContent=d.kicker;
 document.querySelector("#topic-title").textContent=d.title;
 document.querySelector("#topic-deck").textContent=d.deck;
 document.querySelector("#topic-meta").innerHTML=d.meta.map(x=>'<span>'+x+'</span>').join("");
 document.querySelector("#topic-nav-label").textContent=d.nav;
 const nav=document.querySelector("#topic-nav-links");
 const chapters=document.querySelector("#chapters");
 nav.innerHTML=d.chapters.map((ch,i)=>'<a href="#c'+(i+1)+'">'+ch[0]+' · '+ch[1]+'</a>').join("");
 chapters.innerHTML=d.chapters.map((ch,i)=>'<section class="chapter" id="c'+(i+1)+'"><div class="chapter-no">'+ch[0]+'</div><h2>'+ch[1]+'</h2><p>'+ch[2]+'</p><p>'+ch[3]+'</p></section>').join("")+
 '<section class="chapter" id="controls"><div class="chapter-no">'+c.controls+'</div><h2>'+d.checksTitle+'</h2><div class="checks">'+d.checks.map((x,i)=>'<div class="check"><b>0'+(i+1)+'</b><span>'+x+'</span></div>').join("")+'</div><p style="margin-top:24px;font-size:.78rem;color:var(--muted)">'+d.source+'</p></section>';
 document.querySelector("#philo-title").textContent=d.philoTitle;
 document.querySelector("#philo").textContent=d.philo;
 document.querySelector("#back").textContent=d.back;
 if(document.querySelector("#f-inst")){
   document.querySelector("#f-inst").textContent=c.institution;
   document.querySelector("#f-work").textContent=c.work;
   document.querySelector("#f-about").textContent=c.about;
   document.querySelector("#f-standards").textContent=c.standards;
   document.querySelector("#f-contact").textContent=c.contact;
   document.querySelector("#f-research").textContent=c.research;
   document.querySelector("#f-ai").textContent=c.ai;
   document.querySelector("#f-pubs").textContent=c.publications;
   document.querySelector("#f-sovereignty").textContent=c.sovereignty;
   if(document.querySelector("#f-legal")) document.querySelector("#f-legal").textContent=c.legal;
   if(document.querySelector("#f-privacy")) document.querySelector("#f-privacy").textContent=c.privacy;
 }
}
document.addEventListener("DOMContentLoaded",()=>{
 document.querySelectorAll("[data-lang]").forEach(b=>b.addEventListener("click",()=>setLang(b.dataset.lang)));
 renderTopic(currentLang());
});